// BFS 同步
void BFS(vector<vector<int>>& grid, int m, int n) {
    int direct[4][2] = {{-1,0}, {1, 0}, {0, -1}, {0,1}};
    grid[0][0] = 1;
    queue<pair<int,int>> q;
    q.push({0,0});
    while (!q.empty()) {
        pair<int, int> tmp = q.front();
        q.pop();
        int x = tmp.first;
        int y = tmp.second;
        // 四个方向进行同化
        for (int i = 0; i < 4; i++) {
            int newX = x + direct[i][0];
            int newY = y + direct[i][1];
            if (newX < 0 || newX >= m || newY < 0 || newY >= n|| grid[newX][newY] != 0) {
                continue;
            }
            grid[newX][newY] = 1;
            q.push({newX, newY});
        }
    }
}
​
int main() {
    int m,n;
    cin >> m  >> n;
    vector<vector<int>> grid(m, vector<int>(n, 0));       
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            cin >> grid[i][j];
        }
    }
​
    BFS(grid, m, n);
    int res = 0;
    // 统计非1数量
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] != 1) {
                res++;
            }
        }
    }       
    cout << res;
    return 0;
}

