function bfs(grid, m, n) {
    // 定义四个方向
    let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let queue = [[0, 0]];
    grid[0][0] = 1;
​
    while (queue.length > 0) {
        let [x, y] = queue.shift();
        // 往四个方向同化
        for (let [dx, dy] of directions) {
            let newX = x + dx, newY = y + dy;
            if (newX >= 0 && newX < m && newY >= 0 && newY < n && grid[newX][newY] === 0) {
                grid[newX][newY] = 1;
                queue.push([newX, newY]);
            }
        }
    }
}
